"use client";

import { motion, useReducedMotion } from "framer-motion";

const GLOW_NOISE_URL =
  "data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.45'/%3E%3C/svg%3E";

type GlowTone = "mono" | "pinkPurple" | "redBlue" | "yellowGreen" | "limePink";

const GLOW_TONES: Record<GlowTone, { light: string; dark: string }> = {
  mono: {
    light:
      "radial-gradient(circle at 30% 30%, rgba(0,0,0,0.5), rgba(0,0,0,0) 60%), radial-gradient(circle at 70% 40%, rgba(0,0,0,0.4), rgba(0,0,0,0) 60%), radial-gradient(circle at 55% 75%, rgba(0,0,0,0.45), rgba(0,0,0,0) 60%)",
    dark:
      "radial-gradient(circle at 30% 30%, rgba(255,255,255,0.5), rgba(255,255,255,0) 60%), radial-gradient(circle at 70% 40%, rgba(255,255,255,0.4), rgba(255,255,255,0) 60%), radial-gradient(circle at 55% 75%, rgba(255,255,255,0.45), rgba(255,255,255,0) 60%)",
  },
  pinkPurple: {
    light:
      "radial-gradient(circle at 30% 30%, rgba(236,72,153,0.9), rgba(236,72,153,0) 60%), radial-gradient(circle at 70% 40%, rgba(168,85,247,0.85), rgba(168,85,247,0) 60%), radial-gradient(circle at 55% 75%, rgba(190,24,93,0.85), rgba(190,24,93,0) 60%)",
    dark:
      "radial-gradient(circle at 30% 30%, rgba(236,72,153,0.9), rgba(236,72,153,0) 60%), radial-gradient(circle at 70% 40%, rgba(168,85,247,0.85), rgba(168,85,247,0) 60%), radial-gradient(circle at 55% 75%, rgba(190,24,93,0.85), rgba(190,24,93,0) 60%)",
  },
  redBlue: {
    light:
      "radial-gradient(circle at 30% 30%, rgba(239,68,68,0.9), rgba(239,68,68,0) 60%), radial-gradient(circle at 70% 40%, rgba(59,130,246,0.85), rgba(59,130,246,0) 60%), radial-gradient(circle at 55% 75%, rgba(185,28,28,0.85), rgba(185,28,28,0) 60%)",
    dark:
      "radial-gradient(circle at 30% 30%, rgba(239,68,68,0.9), rgba(239,68,68,0) 60%), radial-gradient(circle at 70% 40%, rgba(59,130,246,0.85), rgba(59,130,246,0) 60%), radial-gradient(circle at 55% 75%, rgba(185,28,28,0.85), rgba(185,28,28,0) 60%)",
  },
  yellowGreen: {
    light:
      "radial-gradient(circle at 30% 30%, rgba(234,179,8,0.9), rgba(234,179,8,0) 60%), radial-gradient(circle at 70% 40%, rgba(34,197,94,0.85), rgba(34,197,94,0) 60%), radial-gradient(circle at 55% 75%, rgba(161,98,7,0.85), rgba(161,98,7,0) 60%)",
    dark:
      "radial-gradient(circle at 30% 30%, rgba(234,179,8,0.9), rgba(234,179,8,0) 60%), radial-gradient(circle at 70% 40%, rgba(34,197,94,0.85), rgba(34,197,94,0) 60%), radial-gradient(circle at 55% 75%, rgba(161,98,7,0.85), rgba(161,98,7,0) 60%)",
  },
  limePink: {
    light:
      "radial-gradient(circle at 30% 30%, rgba(132,204,22,0.9), rgba(132,204,22,0) 60%), radial-gradient(circle at 70% 40%, rgba(236,72,153,0.85), rgba(236,72,153,0) 60%), radial-gradient(circle at 55% 75%, rgba(77,124,15,0.85), rgba(77,124,15,0) 60%)",
    dark:
      "radial-gradient(circle at 30% 30%, rgba(132,204,22,0.9), rgba(132,204,22,0) 60%), radial-gradient(circle at 70% 40%, rgba(236,72,153,0.85), rgba(236,72,153,0) 60%), radial-gradient(circle at 55% 75%, rgba(77,124,15,0.85), rgba(77,124,15,0) 60%)",
  },
};

export function GlowCard({
  title,
  description,
  tone = "mono",
}: {
  title: string;
  description: string;
  tone?: GlowTone;
}) {
  const shouldReduceMotion = useReducedMotion();
  const active = GLOW_TONES[tone];

  return (
    <div className="relative w-full max-w-sm py-14">
      <motion.div
        aria-hidden
        className="absolute -inset-10 rounded-[28px] opacity-50 blur-3xl transform-gpu dark:hidden"
        style={{ background: active.light }}
        animate={shouldReduceMotion ? undefined : { x: [0, 14, -10, 0], y: [0, -10, 8, 0] }}
        transition={{ duration: 10, repeat: Infinity, ease: "easeInOut" }}
      />
      <motion.div
        aria-hidden
        className="absolute -inset-10 rounded-[28px] opacity-50 blur-3xl transform-gpu hidden dark:block"
        style={{ background: active.dark }}
        animate={shouldReduceMotion ? undefined : { x: [0, 14, -10, 0], y: [0, -10, 8, 0] }}
        transition={{ duration: 10, repeat: Infinity, ease: "easeInOut" }}
      />
      <div
        aria-hidden
        className="pointer-events-none absolute -inset-28 opacity-40"
        style={{
          backgroundImage: `url("${GLOW_NOISE_URL}")`,
          backgroundSize: "128px 128px",
          backgroundRepeat: "repeat",
          maskImage: "radial-gradient(ellipse at center, black 30%, transparent 70%)",
          WebkitMaskImage: "radial-gradient(ellipse at center, black 30%, transparent 70%)",
        }}
      />
      <div className="relative rounded-2xl border border-slate-200 bg-white p-6 dark:border-slate-800 dark:bg-slate-950">
        <h3 className="text-base font-semibold text-slate-900 dark:text-white">{title}</h3>
        <p className="mt-1.5 text-sm leading-relaxed text-slate-500 dark:text-slate-400">{description}</p>
      </div>
    </div>
  );
}
